import express from 'express';
import { readFile, writeFile } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_FILE = path.join(__dirname, 'data', 'books.json');
const PORT = process.env.PORT || 3000;

async function readBooks() {
  const raw = await readFile(DATA_FILE, 'utf-8');
  return JSON.parse(raw);
}

async function writeBooks(books) {
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2));
}

const app = express();
app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

app.get('/api/books', async (req, res) => {
  const books = await readBooks();
  res.json(books);
});

app.get('/api/books/:id', async (req, res) => {
  const books = await readBooks();
  const book = books.find((b) => b.id === req.params.id);
  if (!book) return res.status(404).json({ error: 'Book not found' });
  res.json(book);
});

app.post('/api/books', async (req, res) => {
  const { title, author, notes } = req.body;
  if (!title || !title.trim()) {
    return res.status(400).json({ error: 'Title is required' });
  }
  const books = await readBooks();
  const book = {
    id: randomUUID(),
    title: title.trim(),
    author: (author || '').trim(),
    notes: (notes || '').trim(),
    status: 'reading',
    addedAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.push(book);
  await writeBooks(books);
  res.status(201).json(book);
});

app.patch('/api/books/:id', async (req, res) => {
  const books = await readBooks();
  const book = books.find((b) => b.id === req.params.id);
  if (!book) return res.status(404).json({ error: 'Book not found' });

  const { notes, status } = req.body;
  if (notes !== undefined) book.notes = notes;
  if (status !== undefined) {
    if (!['reading', 'finished'].includes(status)) {
      return res.status(400).json({ error: 'Invalid status' });
    }
    book.status = status;
    book.finishedAt = status === 'finished' ? new Date().toISOString() : null;
  }

  await writeBooks(books);
  res.json(book);
});

app.delete('/api/books/:id', async (req, res) => {
  const books = await readBooks();
  const next = books.filter((b) => b.id !== req.params.id);
  if (next.length === books.length) return res.status(404).json({ error: 'Book not found' });
  await writeBooks(next);
  res.status(204).end();
});

// Direct links to a book (e.g. shared with someone else) load the same SPA shell.
app.get('/books/:id', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'index.html'));
});

app.listen(PORT, () => {
  console.log(`Book tracker running at http://localhost:${PORT}`);
});

