:root {
  color-scheme: light dark;
  --bg: #faf9f7;
  --text: #23201c;
  --muted: #6b6459;
  --border: #e3ddd3;
  --accent: #a15c38;
  --accent-text: #fff;
  --card-bg: #fff;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #1c1a17;
    --text: #ece7e0;
    --muted: #9a9186;
    --border: #35312b;
    --accent: #d98a5f;
    --accent-text: #1c1a17;
    --card-bg: #242119;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

#app {
  max-width: 720px;
  margin: 0 auto;
  padding: 2rem 1.25rem 4rem;
}

h1 {
  font-size: 1.6rem;
  margin: 0 0 1.5rem;
}

h2.section-title {
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--muted);
  margin: 2rem 0 0.75rem;
}

.top-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.5rem;
}

button, .btn {
  font: inherit;
  cursor: pointer;
  border: 1px solid var(--border);
  background: var(--card-bg);
  color: var(--text);
  border-radius: 8px;
  padding: 0.5rem 0.9rem;
}

button.primary {
  background: var(--accent);
  color: var(--accent-text);
  border-color: var(--accent);
  font-weight: 600;
}

button.subtle {
  border-color: transparent;
  background: transparent;
  color: var(--muted);
}

button:hover {
  filter: brightness(0.97);
}

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.book-card {
  display: block;
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 0.85rem 1rem;
  text-decoration: none;
  color: var(--text);
}

.book-card:hover {
  border-color: var(--accent);
}

.book-card .title {
  font-weight: 600;
}

.book-card .author {
  color: var(--muted);
  font-size: 0.92rem;
}

.empty {
  color: var(--muted);
  font-style: italic;
  padding: 0.5rem 0;
}

form.add-form {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 1rem;
  margin-bottom: 1.5rem;
}

label {
  font-size: 0.85rem;
  color: var(--muted);
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

input, textarea {
  font: inherit;
  padding: 0.5rem 0.6rem;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--bg);
  color: var(--text);
}

textarea {
  resize: vertical;
  min-height: 4.5rem;
}

.form-actions {
  display: flex;
  gap: 0.5rem;
  justify-content: flex-end;
}

.back-link {
  display: inline-block;
  margin-bottom: 1.25rem;
  color: var(--muted);
  text-decoration: none;
}

.back-link:hover {
  color: var(--text);
}

.detail-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
}

.detail-header h1 {
  margin-bottom: 0.15rem;
}

.detail-author {
  color: var(--muted);
  margin: 0 0 1.25rem;
}

.status-pill {
  display: inline-block;
  font-size: 0.75rem;
  padding: 0.2rem 0.55rem;
  border-radius: 999px;
  background: var(--border);
  color: var(--text);
  margin-bottom: 1rem;
}

.detail-actions {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
}

.notes-block textarea {
  width: 100%;
  min-height: 10rem;
}

.notes-label {
  color: var(--muted);
  font-size: 0.85rem;
  margin-bottom: 0.4rem;
  display: block;
}

.toast {
  position: fixed;
  bottom: 1.25rem;
  left: 50%;
  transform: translateX(-50%);
  background: var(--text);
  color: var(--bg);
  padding: 0.5rem 1rem;
  border-radius: 8px;
  font-size: 0.9rem;
  opacity: 0;
  transition: opacity 0.2s ease;
  pointer-events: none;
}

.toast.show {
  opacity: 1;
}

