const app = document.getElementById('app');

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function navigate(path) {
  history.pushState({}, '', path);
  render();
}

document.addEventListener('click', (e) => {
  const link = e.target.closest('a[data-link]');
  if (!link) return;
  e.preventDefault();
  navigate(link.getAttribute('href'));
});

window.addEventListener('popstate', render);

function showToast(message) {
  let toast = document.querySelector('.toast');
  if (!toast) {
    toast = document.createElement('div');
    toast.className = 'toast';
    document.body.appendChild(toast);
  }
  toast.textContent = message;
  toast.classList.add('show');
  clearTimeout(toast._timer);
  toast._timer = setTimeout(() => toast.classList.remove('show'), 1800);
}

async function fetchJson(url, options) {
  const res = await fetch(url, options);
  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
    throw new Error(body.error || `Request failed (${res.status})`);
  }
  if (res.status === 204) return null;
  return res.json();
}

function bookCard(book) {
  return `
    <a class="book-card" href="/books/${book.id}" data-link>
      <div class="title">${escapeHtml(book.title)}</div>
      ${book.author ? `<div class="author">${escapeHtml(book.author)}</div>` : ''}
    </a>
  `;
}

async function renderList() {
  app.innerHTML = `<div class="top-bar"><h1>My Books</h1><button id="add-toggle" class="primary">Add book</button></div>
    <div id="add-form-container"></div>
    <h2 class="section-title">Currently reading</h2>
    <ul class="book-list" id="reading-list"><li class="empty">Loading…</li></ul>
    <h2 class="section-title">Finished</h2>
    <ul class="book-list" id="finished-list"></ul>`;

